func EllipseToCubicBeziers(startX, startY, rx, ry, rot float64, large, sweep bool, endX, endY float64) [][4]Point {
	rx = math.Abs(rx)
	ry = math.Abs(ry)
	if rx < ry {
		rx, ry = ry, rx
		rot += 90.0
	}
	rotRad := normalizeAngle(rot * math.Pi / 180.0)
	if math.Pi <= rotRad {
		rotRad -= math.Pi
	}
	cx, cy, theta1, theta2 := endpointToCenterParams(startX, startY, rx, ry, rotRad, large, sweep, endX, endY)
	segAngle := math.Pi / 2.0
	segCount := int(math.Ceil(math.Abs(theta2-theta1) / segAngle))
	segAngle = math.Abs(theta2-theta1) / float64(segCount)
	alpha := math.Sin(segAngle) * (math.Sqrt(4.0+3.0*math.Pow(math.Tan(segAngle/2.0), 2.0)) - 1.0) / 3.0
	if !sweep {
		segAngle = -segAngle
	}
	prev := Point{X: startX, Y: startY}
	dx, dy := ellipseDerivative(rx, ry, rotRad, sweep, theta1)
	prevDeriv := Point{X: dx, Y: dy}
	curves := [][4]Point{}
	for i := 1; i < segCount+1; i++ {
		theta := theta1 + float64(i)*segAngle
		px, py := ellipsePoint(rx, ry, rotRad, cx, cy, theta)
		pt := Point{X: px, Y: py}
		ddx, ddy := ellipseDerivative(rx, ry, rotRad, sweep, theta)
		deriv := Point{X: ddx, Y: ddy}
		ctrl1 := prev.Add(prevDeriv.Mul(alpha))
		ctrl2 := pt.Sub(deriv.Mul(alpha))
		curves = append(curves, [4]Point{prev, ctrl1, ctrl2, pt})
		prevDeriv = deriv
		prev = pt
	}
	return curves
}

