const epsilon = 1e-10

type Point struct {
	X, Y float64
}

func normalizeAngle(a float64) float64 {
	a = math.Mod(a, 2.0*math.Pi)
	if a < 0.0 {
		a += 2.0 * math.Pi
	}
	return a
}
